package edu.pe.cibertec.saibm.libro;
import static org.assertj.core.api.Assertions.*; import java.nio.file.*; import org.junit.jupiter.api.Test;
class BoundaryContractTest { @Test void domainApplicationAndSchemaStayIndependent(){try{var root=Path.of("src/main/java/edu/pe/cibertec/saibm/libro");for(var area:new String[]{"domain","application"})try(var fs=Files.walk(root.resolve(area))){fs.filter(p->p.toString().endsWith(".java")).forEach(p->{try{assertThat(Files.readString(p)).doesNotContain("org.springframework","jakarta.persistence");}catch(Exception e){throw new RuntimeException(e);}});}assertThat(Files.readString(root.resolve("application/port/in/BookUseCase.java"))).doesNotContain("application.port.out");assertThat(Files.readString(Path.of("src/main/resources/db/migration/V1__libro.sql"))).doesNotContain("inventory","stock","hold");}catch(Exception e){throw new RuntimeException(e);}} @Test void persistenceAndRestRemainOutsideApplication(){try{var root=Path.of("src/main/java/edu/pe/cibertec/saibm/libro");assertThat(Files.readString(root.resolve("infrastructure/out/persistence/BookJpaEntity.java"))).contains("jakarta.persistence");assertThat(Files.readString(root.resolve("infrastructure/in/rest/BookController.java"))).contains("@RestController");}catch(Exception e){throw new RuntimeException(e);}} }
